type OAuthTokenResponse = { access_token: string; refresh_token?: string; expires_in?: number; scope?: string };
type EtsyMoney = { amount?: number | string; divisor?: number | string; currency_code?: string };
type EtsyImage = { url_fullxfull?: string; url_570xN?: string; url_170x135?: string; url?: string };
type EtsyProduct = { sku?: unknown; offerings?: { sku?: unknown }[] };
type EtsyListing = {
  sku?: unknown; inventory?: { products?: EtsyProduct[] }; products?: EtsyProduct[];
  images?: EtsyImage[]; Images?: EtsyImage[]; description?: string; listing_id?: string | number;
  title?: string; price?: EtsyMoney; quantity?: number; state?: string; url?: string;
  taxonomy_id?: number | string; num_favorers?: number;
};
type EtsyReceipt = {
  receipt_id?: number | string; status?: string; name?: string; buyer_email?: string;
  country_iso?: string; city?: string; state?: string; zip?: string;
  tracking_code?: string; carrier_name?: string;
  shipments?: { tracking_code?: string; carrier_name?: string }[];
  grandtotal?: EtsyMoney; created_timestamp?: number;
  transactions?: { transaction_id?: number | string; listing_id?: number | string; sku?: string;
    title?: string; quantity?: number; price?: EtsyMoney; image_url?: string }[];
};
type EtsyShop = { shop_id?: number | string; shop_name?: string };

const API_BASE = "https://openapi.etsy.com";
const AUTH_URL = "https://www.etsy.com/oauth/connect";
const TOKEN_URL = "https://api.etsy.com/v3/public/oauth/token";
const SCOPES = "listings_r listings_w transactions_r shops_r";
const ETSY_APP_PROFILES: EtsyOAuthAppProfile[] = [
  "ETSY_SELLER_LEGACY",
  "ETSY_SECONDARY",
  "ETSY_PERSONAL",
  "ETSY_COMMERCIAL",
];
type EtsyTaxonomyNode = {
  taxonomy_id?: string | number;
  id?: string | number;
  name?: string;
  children?: EtsyTaxonomyNode[];
};
type EtsyTaxonomyPropertyValue = string | {
  value_id?: string | number;
  id?: string | number;
  name?: string;
  value?: string;
};
type EtsyTaxonomyProperty = {
  property_id?: string | number;
  id?: string | number;
  display_name?: string;
  name?: string;
  required?: boolean;
  is_required?: boolean;
  possible_values?: EtsyTaxonomyPropertyValue[];
  supports_variations?: boolean;
};
type EtsyShopSection = { shop_section_id?: string | number; id?: string | number; title?: string };
let sellerTaxonomyCache: { expiresAt: number; nodes: EtsyTaxonomyNode[] } | null = null;

export interface EtsyAppCredentials {
  clientId: string;
  sharedSecret: string;
  redirectUri: string;
}

export type EtsyMarketplaceDraftInput = {
  draftSettings?: DraftSettings;
  title: string;
  sku: string;
  description: string;
  quantity: number;
  price: number;
  taxonomyId: string;
  shopSectionId?: string;
  whoMade: "I_DID" | "SHOP_MEMBER" | "ANOTHER_COMPANY_OR_PERSON";
  whenMade: string;
  isSupply: boolean;
  tags: string[];
  categoryAttributes: Array<{
    propertyId?: string;
    valueId?: string;
    value: string;
  }>;
  media: Array<{ mediaUrl: string; type: "IMAGE" | "VIDEO" }>;
};

function env(name: string): string {
  return (process.env[name] || "").trim();
}

/** Unknown/missing legacy values deliberately resolve to the existing app. */
export function normalizeEtsyAppProfile(value: unknown): EtsyOAuthAppProfile {
  return ETSY_APP_PROFILES.includes(value as EtsyOAuthAppProfile)
    ? value as EtsyOAuthAppProfile
    : "ETSY_SELLER_LEGACY";
}

export function isEtsyAppProfile(value: unknown): value is EtsyOAuthAppProfile {
  return typeof value === "string" && ETSY_APP_PROFILES.includes(value as EtsyOAuthAppProfile);
}

/**
 * App credentials are process configuration, never connection data. Personal
 * and Commercial profiles are intentionally unavailable until approved
 * credentials are explicitly added; silently falling back would be unsafe.
 */
export function resolveEtsyCredentials(profile: EtsyOAuthAppProfile): EtsyAppCredentials {
  if (profile === "ETSY_SELLER_LEGACY") {
    return {
      clientId: env("ETSY_CLIENT_ID") || env("ETSY_API_KEY") || env("ETSY_KEYSTRING"),
      sharedSecret: env("ETSY_SHARED_SECRET") || env("ETSY_API_SECRET"),
      redirectUri: env("ETSY_REDIRECT_URI"),
    };
  }
  if (profile === "ETSY_SECONDARY") {
    return {
      clientId: env("ETSY_SECONDARY_CLIENT_ID"),
      sharedSecret: env("ETSY_SECONDARY_SHARED_SECRET"),
      redirectUri: env("ETSY_SECONDARY_REDIRECT_URI"),
    };
  }
  throw new Error(`${profile} has no configured Etsy credential set.`);
}

export async function isEtsyProfileConfigured(profile: EtsyOAuthAppProfile): Promise<boolean> {
  try {
    const credentials = resolveEtsyCredentials(profile);
    return Boolean(credentials.clientId && credentials.sharedSecret && credentials.redirectUri);
  } catch {
    return false;
  }
}

function moneyValue(money: EtsyMoney | undefined): number | null {
  if (!money) return null;
  const amount = Number(money.amount);
  const divisor = Number(money.divisor) || 1;
  if (!Number.isFinite(amount)) return null;
  return amount / divisor;
}

function moneyCurrency(money: EtsyMoney | undefined): string | null {
  return money?.currency_code ? String(money.currency_code) : null;
}

function usableSku(value: unknown): string | null {
  if (typeof value !== "string" && typeof value !== "number") return null;
  const sku = String(value).trim();
  return sku || null;
}

/**
 * Etsy keeps a listing SKU on an inventory product, rather than on the
 * listing itself. A legacy direct `sku` is also accepted because saved API
 * payloads and older responses can use that shape.
 */
export function etsyListingSku(listing: EtsyListing | null | undefined): string | null {
  const directValues = Array.isArray(listing?.sku) ? listing.sku : [listing?.sku];
  for (const value of directValues) {
    const direct = usableSku(value && typeof value === "object" ? ("sku" in value ? value.sku : undefined) : value);
    if (direct) return direct;
  }

  const products = listing?.inventory?.products;
  if (Array.isArray(products)) {
    for (const product of products) {
      const productSku = usableSku(product?.sku);
      if (productSku) return productSku;
      for (const offering of Array.isArray(product?.offerings) ? product.offerings : []) {
        const offeringSku = usableSku(offering?.sku);
        if (offeringSku) return offeringSku;
      }
    }
  }

  // Some Etsy integrations serialize product inventory directly on `products`.
  for (const product of Array.isArray(listing?.products) ? listing.products : []) {
    const productSku = usableSku(product?.sku);
    if (productSku) return productSku;
  }

  // Our product descriptions also carry the ERP SKU. Only use an explicitly
  // labelled value so normal prose can never be accidentally mapped.
  const description = typeof listing?.description === "string"
    ? listing.description.replace(/<[^>]*>/g, " ")
    : "";
  const labelledSku = description.match(/\bSKU\s*(?:No\.?|Number|Code)?\s*[:#-]\s*([A-Za-z0-9][A-Za-z0-9._/-]{2,80})\b/i);
  return labelledSku?.[1] || null;
}

export function etsyListingImages(listing: EtsyListing | null | undefined): string[] {
  const candidates = Array.isArray(listing?.images)
    ? listing.images
    : Array.isArray(listing?.Images)
      ? listing.Images
      : [];
  return candidates
    .map((image) => image?.url_fullxfull || image?.url_570xN || image?.url_170x135 || image?.url || "")
    .filter((url: unknown): url is string => typeof url === "string" && url.length > 0);
}

function base64Url(input: Buffer): string {
  return input.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function generateCodeVerifier(): string {
  return base64Url(crypto.randomBytes(48));
}

function codeChallengeFromVerifier(verifier: string): string {
  return base64Url(crypto.createHash("sha256").update(verifier).digest());
}

async function storePkceVerifier(state: string, verifier: string): Promise<void> {
  await prisma.setting.upsert({
    where: { key: `etsy_pkce_${state}` },
    create: { key: `etsy_pkce_${state}`, value: verifier },
    update: { value: verifier },
  });
}

async function consumePkceVerifier(state: string): Promise<string | null> {
  const row = await prisma.setting.findUnique({ where: { key: `etsy_pkce_${state}` } });
  if (!row?.value) return null;
  await prisma.setting.delete({ where: { key: `etsy_pkce_${state}` } }).catch(() => {});
  return row.value;
}

export class EtsyConnector implements MarketplaceConnector {
  readonly platform = "ETSY" as const;

  private credentials(profile: EtsyOAuthAppProfile): EtsyAppCredentials {
    const credentials = resolveEtsyCredentials(profile);
    if (!credentials.clientId || !credentials.sharedSecret || !credentials.redirectUri) {
      throw new Error(`${profile} is not configured with Etsy client credentials.`);
    }
    return credentials;
  }

  async isConfigured(): Promise<boolean> {
    return isEtsyProfileConfigured("ETSY_SELLER_LEGACY");
  }

  async getAuthorizationUrl(state: string, context?: MarketplaceOAuthContext): Promise<string> {
    const profile = normalizeEtsyAppProfile(context?.appProfile);
    const credentials = this.credentials(profile);
    const verifier = generateCodeVerifier();
    const challenge = codeChallengeFromVerifier(verifier);
    await storePkceVerifier(state, verifier);
    const params = new URLSearchParams({
      response_type: "code",
      redirect_uri: credentials.redirectUri,
      scope: SCOPES,
      client_id: credentials.clientId,
      state,
      code_challenge: challenge,
      code_challenge_method: "S256",
    });
    return `${AUTH_URL}?${params.toString()}`;
  }

  async exchangeAuthorizationCode(code: string, state?: string, context?: MarketplaceOAuthContext): Promise<MarketplaceOAuthResult> {
    if (!(await isEncryptionReady())) {
      throw new Error("Secret encryption key is not configured; cannot store Etsy tokens.");
    }
    const verifier = state ? await consumePkceVerifier(state) : null;
    if (!verifier) throw new Error("Missing or already-used Etsy PKCE verifier.");
    const profile = normalizeEtsyAppProfile(context?.appProfile);
    const credentials = this.credentials(profile);
    const body = new URLSearchParams({
      grant_type: "authorization_code",
      client_id: credentials.clientId,
      redirect_uri: credentials.redirectUri,
      code,
    });
    body.set("code_verifier", verifier);

    const data = await httpJson<OAuthTokenResponse>(TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: body.toString(),
    });

    const tokens = {
      accessToken: data.access_token,
      refreshToken: data.refresh_token,
      expiresAt: data.expires_in ? new Date(Date.now() + data.expires_in * 1000).toISOString() : null,
      scope: resolveOAuthScopes(data.scope, SCOPES),
    };
    const externalAccountId = String(tokens.accessToken.split(".")[0] || "").trim();
    if (!externalAccountId) throw new Error("Etsy did not return an account ID in the OAuth token.");
    const shops = await this.getUserShops(tokens.accessToken, this.getHeaders(tokens.accessToken, credentials));
    return {
      externalAccountId,
      accountName: externalAccountId,
      tokens,
      shops: shops
        .filter((shop) => shop?.shop_id)
        .map((shop) => ({ externalShopId: String(shop.shop_id), name: String(shop.shop_name || shop.shop_id) })),
    };
  }

  private async getAccessToken(connectionId: string): Promise<string> {
    const profile = await this.getConnectionProfile(connectionId);
    return getValidAccessToken(connectionId, (tokens) =>
      this.refreshAccessToken(connectionId, tokens.refreshToken!, tokens.scope, profile)
    );
  }

  private async getConnectionProfile(connectionId: string): Promise<EtsyOAuthAppProfile> {
    const connection = await prisma.marketplaceConnection.findUnique({
      where: { id: connectionId },
      select: { marketplace: true, oauthAppProfile: true },
    });
    if (!connection || connection.marketplace !== "ETSY") throw new Error("Etsy connection was not found.");
    return normalizeEtsyAppProfile(connection.oauthAppProfile);
  }

  private async refreshAccessToken(connectionId: string, refreshToken: string, scope: string | null | undefined, profile: EtsyOAuthAppProfile): Promise<string> {
    const credentials = this.credentials(profile);
    const body = new URLSearchParams({
      grant_type: "refresh_token",
      client_id: credentials.clientId,
      refresh_token: refreshToken,
    });
    const data = await httpJson<OAuthTokenResponse>(TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: body.toString(),
    });
    await updateTokens(connectionId, {
      accessToken: data.access_token,
      refreshToken: data.refresh_token || refreshToken,
      expiresAt: data.expires_in ? new Date(Date.now() + data.expires_in * 1000).toISOString() : null,
      scope: resolveOAuthScopes(data.scope, scope),
    });
    return data.access_token;
  }

  private getHeaders(token: string, credentials: EtsyAppCredentials): Record<string, string> {
    const apiKey = `${credentials.clientId}:${credentials.sharedSecret}`;
    return {
      ...bearerAuth(token),
      "x-api-key": apiKey,
      Accept: "application/json",
    };
  }

  /** Resolve the authenticating user's shop(s). Returns an array regardless of shape. */
  private async getUserShops(token: string, headers: Record<string, string>): Promise<EtsyShop[]> {
    const userId = String(token.split(".")[0] || "").trim();
    const url = userId
      ? `${API_BASE}/v3/application/users/${userId}/shops`
      : `${API_BASE}/v3/application/shops`;
    const data = await httpJson<EtsyShop & { results?: EtsyShop[] }>(url, { headers }).catch((e) => {
      const err = e as { message?: string; body?: unknown };
      console.error("[etsy] getUserShops failed:", err.message, err.body ? JSON.stringify(err.body) : "");
      throw new Error(`Unable to load Etsy shops: ${err.message || "Marketplace API request failed"}`);
    });
    if (Array.isArray(data?.results)) return data.results;
    if (data?.shop_id) return [data];
    return [];
  }

  async getListingPreparationOptions(
    connectionId: string,
    externalShopId: string,
    taxonomyId?: string
  ): Promise<{
    categories: Array<{ taxonomyId: string; name: string; path: string }>;
    sections: Array<{ id: string; title: string }>;
    sensitivePropertiesExcluded: number;
    properties: Array<{
      id: string;
      name: string;
      required: boolean;
      values: Array<{ id: string | null; name: string }>;
      supportsVariations: boolean;
    }>;
  }> {
    const token = await this.getAccessToken(connectionId);
    const profile = await this.getConnectionProfile(connectionId);
    const credentials = this.credentials(profile);
    const headers = this.getHeaders(token, credentials);

    const taxonomyPromise = async (): Promise<EtsyTaxonomyNode[]> => {
      if (sellerTaxonomyCache && sellerTaxonomyCache.expiresAt > Date.now()) return sellerTaxonomyCache.nodes;
      const response = await httpJson<{ results?: EtsyTaxonomyNode[]; taxonomy_nodes?: EtsyTaxonomyNode[] }>(
        `${API_BASE}/v3/application/seller-taxonomy/nodes`,
        { headers }
      );
      const nodes = Array.isArray(response?.results)
        ? response.results
        : Array.isArray(response?.taxonomy_nodes)
          ? response.taxonomy_nodes
          : [];
      if (!nodes.length) throw new Error("Etsy returned an empty seller taxonomy.");
      sellerTaxonomyCache = { nodes, expiresAt: Date.now() + 60 * 60 * 1000 };
      return nodes;
    };
    const [taxonomyNodes, sectionResponse, propertyResponse] = await Promise.all([
      taxonomyPromise(),
      httpJson<{ results?: EtsyShopSection[] }>(
        `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/sections?limit=100`,
        { headers }
      ),
      taxonomyId
        ? httpJson<{ results?: EtsyTaxonomyProperty[] }>(
            `${API_BASE}/v3/application/seller-taxonomy/nodes/${encodeURIComponent(taxonomyId)}/properties`,
            { headers }
          )
        : Promise.resolve({ results: [] }),
    ]);

    const categories: Array<{ taxonomyId: string; name: string; path: string }> = [];
    const walk = (nodes: EtsyTaxonomyNode[], parents: string[] = []) => {
      for (const node of nodes) {
        const id = node?.taxonomy_id ?? node?.id;
        const name = typeof node?.name === "string" ? node.name.trim() : "";
        if (!id || !name) continue;
        const path = [...parents, name];
        categories.push({ taxonomyId: String(id), name, path: path.join(" > ") });
        walk(Array.isArray(node.children) ? node.children : [], path);
      }
    };
    walk(taxonomyNodes);
    if (!categories.length) {
      throw new Error("Etsy returned no seller taxonomy categories. Check the Etsy API response and shop authorization.");
    }
    if (!Array.isArray(sectionResponse?.results) || (taxonomyId && !Array.isArray(propertyResponse?.results))) {
      throw new Error("Etsy returned an unexpected response while loading shop sections or category properties.");
    }

    const rawProperties = Array.isArray(propertyResponse?.results) ? propertyResponse.results : [];
    const sensitivePropertiesExcluded = rawProperties.filter((property) =>
      /certific|laboratory|certificate number/i.test(String(property?.display_name || property?.name || ""))
    ).length;
    const properties = rawProperties
      .flatMap((property) => {
        const id = property?.property_id ?? property?.id;
        const name = typeof (property?.display_name || property?.name) === "string"
          ? String(property.display_name || property.name).trim()
          : "";
        if (!id || !name || /certific|laboratory|certificate number/i.test(name)) return [];
        const values = Array.isArray(property?.possible_values)
          ? property.possible_values
            .flatMap((value) => {
              const name = typeof value === "string" ? value : value?.name || value?.value;
              return typeof name === "string" && name.trim()
                ? [{ id: value && typeof value === "object" && (value.value_id ?? value.id) != null ? String(value.value_id ?? value.id) : null, name: name.trim() }]
                : [];
            })
          : [];
        return [{
          id: String(id),
          name,
          required: Boolean(property?.required ?? property?.is_required),
          values,
          supportsVariations: Boolean(property?.supports_variations),
        }];
      });

    return {
      categories,
      sections: (Array.isArray(sectionResponse?.results) ? sectionResponse.results : [])
        .flatMap((section) => {
          const id = section?.shop_section_id ?? section?.id;
          const title = typeof section?.title === "string" ? section.title.trim() : "";
          return id && title ? [{ id: String(id), title }] : [];
        }),
      sensitivePropertiesExcluded,
      properties,
    };
  }

  async getShopCurrencyCode(connectionId: string, externalShopId: string): Promise<string> {
    const token = await this.getAccessToken(connectionId);
    const profile = await this.getConnectionProfile(connectionId);
    const credentials = this.credentials(profile);
    const shop = await httpJson<{ currency_code?: string }>(
      `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}`,
      { headers: this.getHeaders(token, credentials) }
    );
    const currencyCode = String(shop.currency_code || "").trim().toUpperCase();
    if (!currencyCode) throw new Error("Etsy did not return the selected shop's listing currency.");
    return currencyCode;
  }

  async getDraftSettingGroups(connectionId: string, externalShopId: string): Promise<DraftSettingGroup[]> {
    const token = await this.getAccessToken(connectionId);
    const credentials = this.credentials(await this.getConnectionProfile(connectionId));
    const headers = this.getHeaders(token, credentials);
    const loadProfiles = async (resource: string, paginated: boolean): Promise<Array<Record<string, unknown>>> => {
      const profiles: Array<Record<string, unknown>> = [];
      for (let offset = 0; ; offset += 100) {
        const data = await httpJson<{ results?: Array<Record<string, unknown>>; count?: number }>(
          `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/${resource}${paginated ? `?limit=100&offset=${offset}` : ""}`,
          { headers }
        );
        if (!Array.isArray(data.results)) throw new Error(`Etsy returned an unexpected response for ${resource}. Reload shop settings.`);
        profiles.push(...data.results);
        if (!paginated || data.results.length < 100 || (data.count != null && profiles.length >= data.count)) break;
      }
      return profiles;
    };
    const [shipping, processing] = await Promise.all([loadProfiles("shipping-profiles", false), loadProfiles("readiness-state-definitions", true)]);
    return [
      makeDraftSettingGroup("shippingProfileId", "Shipping profile", shipping.flatMap((profile) => profile.shipping_profile_id != null
        ? [{ id: String(profile.shipping_profile_id), name: String(profile.title || `Shipping profile ${profile.shipping_profile_id}`) }] : [])),
      makeDraftSettingGroup("readinessStateId", "Processing profile", processing.flatMap((profile) => profile.readiness_state_id != null
        ? [{ id: String(profile.readiness_state_id), name: `${String(profile.readiness_state || "Processing").replaceAll("_", " ")} · ${profile.min_processing_time ?? "?"}–${profile.max_processing_time ?? "?"} ${profile.processing_time_unit || "days"}` }] : [])),
    ];
  }

  async createMarketplaceDraft(
    connectionId: string,
    externalShopId: string,
    input: EtsyMarketplaceDraftInput
  ): Promise<{ listingId: string; uploadedMedia: number; warnings: string[]; draftSettings: DraftSettings }> {
    if (!input.sku.trim()) throw new Error("Inventory SKU is missing. Add it before creating an Etsy draft.");
    const validationErrors = etsyDraftValidationErrors(input);
    if (validationErrors.length) throw new Error(validationErrors.join(" "));
    const draftSettings = resolveDraftSettings(await this.getDraftSettingGroups(connectionId, externalShopId), input.draftSettings);
    const token = await this.getAccessToken(connectionId);
    const profile = await this.getConnectionProfile(connectionId);
    const credentials = this.credentials(profile);
    const headers = this.getHeaders(token, credentials);
    const form = new URLSearchParams({
      quantity: String(input.quantity),
      title: input.title.normalize("NFC"),
      description: etsyPlainText(input.description),
      price: input.price.toFixed(2),
      who_made: input.whoMade === "I_DID" ? "i_did" : input.whoMade === "SHOP_MEMBER" ? "collective" : "someone_else",
      when_made: input.whenMade.toLowerCase(),
      taxonomy_id: input.taxonomyId,
      is_supply: String(input.isSupply),
      type: "physical",
      shipping_profile_id: draftSettings.shippingProfileId!,
      readiness_state_id: draftSettings.readinessStateId!,
    });
    if (input.shopSectionId) form.set("shop_section_id", input.shopSectionId);
    if (input.tags.length) form.set("tags", input.tags.join(","));

    const created = await httpJson<{ listing_id?: number | string }>(
      `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/listings?legacy=false`,
      {
        method: "POST",
        headers: { ...headers, "Content-Type": "application/x-www-form-urlencoded" },
        body: form.toString(),
      },
      // Creating a draft is not idempotent: retrying a lost response can create duplicates.
      { maxRetries: 0 }
    ).catch((error: unknown) => {
      if (error instanceof HttpError) throw new HttpError(`Etsy draft creation failed (HTTP ${error.status})`, error.status, error.body);
      throw error;
    });
    const listingId = String(created.listing_id || "").trim();
    if (!listingId) throw new Error("Etsy accepted the draft request but did not return a listing ID.");

    const warnings: string[] = [];
    let uploadedMedia = 0;
    let imageRank = 1;
    try {
      await this.saveDraftSku(connectionId, listingId, input.sku, { price: input.price, quantity: input.quantity, readinessStateId: draftSettings.readinessStateId! });
    } catch (error) {
      warnings.push(`SKU: ${error instanceof Error ? error.message : "update failed"}`);
    }
    try {
      warnings.push(...await this.updateDraftAttributes(connectionId, externalShopId, listingId, input.categoryAttributes));
    } catch (error) {
      // Preserve the created listing ID even if checking/applying its attributes fails.
      warnings.push(`Category attribute updates: ${error instanceof Error ? error.message : "update failed"}`);
    }
    for (const [index, asset] of input.media.entries()) {
      try {
        const file = await downloadMarketplaceMedia(
          asset.mediaUrl,
          asset.type,
          asset.type === "IMAGE" ? 10 * 1024 * 1024 : 100 * 1024 * 1024
        );
        const body = new FormData();
        body.append(
          asset.type === "IMAGE" ? "image" : "video",
          new Blob([Uint8Array.from(file.buffer)], { type: file.contentType }),
          file.fileName
        );
        if (asset.type === "IMAGE") {
          body.append("rank", String(imageRank));
          imageRank += 1;
          await httpRequest(
            `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/listings/${encodeURIComponent(listingId)}/images`,
            { method: "POST", headers, body }
          );
        } else {
          body.append("name", file.fileName);
          await httpRequest(
            `${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/listings/${encodeURIComponent(listingId)}/videos`,
            { method: "POST", headers, body }
          );
        }
        uploadedMedia += 1;
      } catch (error) {
        warnings.push(`${asset.type === "IMAGE" ? "Photo" : "Video"} ${index + 1}: ${error instanceof Error ? error.message : "upload failed"}`);
      }
    }

    return { listingId, uploadedMedia, warnings, draftSettings };
  }

  async saveDraftSku(connectionId: string, listingId: string, sku: string, initial?: { price: number; quantity: number; readinessStateId: string }): Promise<void> {
    if (!sku.trim()) throw new Error("Inventory SKU is missing.");
    const token = await this.getAccessToken(connectionId);
    const headers = this.getHeaders(token, this.credentials(await this.getConnectionProfile(connectionId)));
    const listing = await httpJson<{ state?: string }>(`${API_BASE}/v3/application/listings/${encodeURIComponent(listingId)}`, { headers });
    if (listing.state !== "draft") throw new Error("This Etsy listing is no longer a draft.");
    const url = `${API_BASE}/v3/application/listings/${encodeURIComponent(listingId)}/inventory`;
    const existing = initial ? null : await httpJson<EtsySkuInventory>(url, { headers });
    // A verified match requires no inventory PUT, preserving seller-entered regional prices.
    if (existing?.products?.length === 1 && existing.products[0].sku === sku) return;
    const products = initial ? [{ sku, property_values: [], offerings: [{ price: initial.price, quantity: initial.quantity, is_enabled: true, readiness_state_id: Number(initial.readinessStateId) }] }] : etsySkuRepairProducts(existing!, sku);
    await httpJson(url, { method: "PUT", headers: { ...headers, "Content-Type": "application/json" }, body: JSON.stringify({ products, price_on_property: [], quantity_on_property: [], sku_on_property: [], readiness_state_on_property: [] }) });
    const verified = await httpJson<EtsySkuInventory>(url, { headers });
    if (verified.products?.length !== 1 || verified.products[0].sku !== sku) throw new Error("Etsy did not confirm the inventory SKU. Retry SKU sync on the saved draft.");
  }

  async updateDraftAttributes(connectionId: string, externalShopId: string, listingId: string, attributes: EtsyDraftAttribute[]): Promise<string[]> {
    const token = await this.getAccessToken(connectionId);
    const headers = this.getHeaders(token, this.credentials(await this.getConnectionProfile(connectionId)));
    // Never repair attributes on a published item through the draft workflow.
    const listing = await httpJson<{ state?: string }>(`${API_BASE}/v3/application/listings/${encodeURIComponent(listingId)}`, { headers });
    if (listing.state !== "draft") throw new Error("This Etsy listing is no longer a draft. Review it in Etsy before changing attributes.");
    const warnings: string[] = [];
    for (const [index, attribute] of attributes.entries()) {
      if (!attribute.propertyId) continue;
      try {
        await httpRequest(`${API_BASE}/v3/application/shops/${encodeURIComponent(externalShopId)}/listings/${encodeURIComponent(listingId)}/properties/${encodeURIComponent(attribute.propertyId)}`, {
          method: "PUT", headers: { ...headers, "Content-Type": "application/x-www-form-urlencoded" }, body: etsyPropertyForm(attribute).toString(),
        });
      } catch (error) {
        warnings.push(`Category attribute ${attribute.name || index + 1} (property ${attribute.propertyId}): ${error instanceof Error ? error.message : "update failed"}`);
      }
    }
    return warnings;
  }

  async fetchListings(params: ListingSyncParams, context: MarketplaceConnectionContext): Promise<NormalizedListing[]> {
    const token = await this.getAccessToken(context.connectionId);
    const headers = this.getHeaders(token, this.credentials(await this.getConnectionProfile(context.connectionId)));
    const pageSize = params.limit && params.limit > 0 ? Math.min(params.limit, 100) : 100;
    const offset = params.offset || 0;
    const data = await httpJson<{ results?: EtsyListing[]; count?: number }>(
      `${API_BASE}/v3/application/shops/${encodeURIComponent(context.externalShopId)}/listings?state=active&includes=Images,Inventory&limit=${pageSize}&offset=${offset}`,
      { headers }
    );
    return (data.results || []).map((listing) => ({
      ...this.normalizeListing(listing),
      marketplaceShopId: context.shopId,
      externalShopId: context.externalShopId,
      shopName: context.shopName,
    }));
  }

  private normalizeListing(listing: EtsyListing | null | undefined): NormalizedListing {
    const sku = etsyListingSku(listing);
    const images = etsyListingImages(listing);

    return {
      marketplace: "ETSY",
      listingId: listing?.listing_id ? String(listing.listing_id) : "",
      listingSku: sku,
      title: listing?.title ? String(listing.title) : null,
      description: listing?.description ? String(listing.description) : null,
      price: moneyValue(listing?.price),
      currency: moneyCurrency(listing?.price),
      quantity: listing?.quantity != null ? Number(listing.quantity) : null,
      status: listing?.state ? String(listing.state) : null,
      listingUrl: listing?.url ? String(listing.url) : null,
      category: listing?.taxonomy_id ? String(listing.taxonomy_id) : null,
      images,
      attributes: {},
      views: null,
      favorites: listing?.num_favorers != null ? Number(listing.num_favorers) : null,
      orders: null,
      raw: listing,
    };
  }

  async fetchOrders(params: OrderSyncParams, context: MarketplaceConnectionContext): Promise<NormalizedOrder[]> {
    const token = await this.getAccessToken(context.connectionId);
    const headers = this.getHeaders(token, this.credentials(await this.getConnectionProfile(context.connectionId)));
    const pageSize = params.limit && params.limit > 0 ? Math.min(params.limit, 100) : 50;
    const offset = params.offset || 0;

    const receipts = await httpJson<{ results?: EtsyReceipt[] }>(
      `${API_BASE}/v3/application/shops/${encodeURIComponent(context.externalShopId)}/receipts?limit=${pageSize}&offset=${offset}`,
      { headers }
    );
    return Promise.all((receipts.results || []).map(async (receipt) => {
      const imagesByListing = await this.getReceiptListingImages(
        context.externalShopId,
        receipt?.receipt_id,
        headers
      ).catch(() => new Map<string, string>());
      return {
        ...this.normalizeOrder(receipt, imagesByListing),
        marketplaceShopId: context.shopId,
        externalShopId: context.externalShopId,
        shopName: context.shopName,
      };
    }));
  }

  /** Etsy receipt transactions do not consistently include images. Load the
   * listing association for the receipt so each synced order item has one. */
  private async getReceiptListingImages(
    shopId: string,
    receiptId: unknown,
    headers: Record<string, string>
  ): Promise<Map<string, string>> {
    const id = String(receiptId || "").trim();
    if (!id) return new Map();
    const data = await httpJson<{ results?: EtsyListing[] }>(
      `${API_BASE}/v3/application/shops/${encodeURIComponent(shopId)}/receipts/${encodeURIComponent(id)}/listings?includes=Images&limit=100`,
      { headers }
    );
    const result = new Map<string, string>();
    await Promise.all((data.results || []).map(async (listing) => {
      try {
        if (listing?.listing_id == null) return;
        const listingId = String(listing.listing_id);
        // getListingsByShopReceipt does not guarantee expanded image payloads.
        // Fetch the image resource directly so receipt thumbnails are reliable.
        let image = etsyListingImages(listing)[0];
        if (!image) {
          const imageData = await httpJson<{ results?: EtsyImage[] }>(
            `${API_BASE}/v3/application/listings/${encodeURIComponent(listingId)}/images?limit=1`,
            { headers }
          );
          image = etsyListingImages({ images: imageData.results })[0];
        }
        if (image) result.set(listingId, image);
      } catch (error) {
        // One unavailable/deleted listing must not hide images for the rest of
        // the receipt. The order itself remains safe to sync.
        console.warn("[etsy] Could not load an order item image:", error);
      }
    }));
    return result;
  }

  private normalizeOrder(receipt: EtsyReceipt, imagesByListing = new Map<string, string>()): NormalizedOrder {
    const items: NormalizedOrderItem[] = (receipt?.transactions || []).map((tx) => ({
      itemId: tx?.transaction_id ? String(tx.transaction_id) : null,
      listingId: tx?.listing_id != null ? String(tx.listing_id) : null,
      sku: tx?.sku ? String(tx.sku) : null,
      title: tx?.title ? String(tx.title) : null,
      quantity: Number(tx?.quantity || 1),
      unitPrice: moneyValue(tx?.price),
      currency: moneyCurrency(tx?.price),
      // Retain the image on the item payload; MarketplaceOrderItem already
      // persists raw source metadata and needs no schema migration for this.
      raw: { ...tx, imageUrl: imagesByListing.get(String(tx?.listing_id || "")) || tx?.image_url || null },
    }));

    return {
      marketplace: "ETSY",
      orderId: receipt?.receipt_id ? String(receipt.receipt_id) : "",
      orderNumber: receipt?.receipt_id ? String(receipt.receipt_id) : null,
      status: receipt?.status ? String(receipt.status) : null,
      buyerName: receipt?.name ? String(receipt.name) : null,
      buyerEmail: receipt?.buyer_email ? String(receipt.buyer_email) : null,
      buyerCountry: receipt?.country_iso ? String(receipt.country_iso) : null,
      buyerCity: receipt?.city ? String(receipt.city) : null,
      buyerState: receipt?.state ? String(receipt.state) : null,
      buyerZip: receipt?.zip ? String(receipt.zip) : null,
      trackingCode: receipt?.shipments?.[0]?.tracking_code
        ? String(receipt.shipments[0].tracking_code)
        : receipt?.tracking_code ? String(receipt.tracking_code) : null,
      carrier: receipt?.shipments?.[0]?.carrier_name
        ? String(receipt.shipments[0].carrier_name)
        : receipt?.carrier_name ? String(receipt.carrier_name) : null,
      orderTotal: moneyValue(receipt?.grandtotal),
      currency: moneyCurrency(receipt?.grandtotal),
      orderDate: receipt?.created_timestamp ? new Date(receipt.created_timestamp * 1000) : null,
      items,
      raw: receipt,
    };
  }
}
